SHORT_COLORS={}
for k,v in COLORS.items():
    if v not in SHORT_COLORS or len(k)<len(SHORT_COLORS[v]):SHORT_COLORS[v]=k

NUM=r'[+-]?(?:\d*\.\d+|\d+\.?\d*)(?:[eE][+-]?\d+)?'
LENGTH_UNITS={'px','em','rem','vw','vh','vmin','vmax','ch','ex','cap','ic','lh','rlh','cm','mm','q','in','pt','pc','svw','svh','lvw','lvh','dvw','dvh','vi','vb','svi','svb','lvi','lvb','dvi','dvb','cqw','cqh','cqi','cqb','cqmin','cqmax'}

def num(x,precision=6):
    try:
        x=float(x)
        if abs(x)<0.00000005:x=0
        if x==int(x):return str(int(x))
        s=format(x,f'.{precision}f').rstrip('0').rstrip('.')
        if s.startswith('0.'):s=s[1:]
        if s.startswith('-0.'):s='-'+s[2:]
        return s
    except:return str(x)

def css_string(s):
    if len(s)>1 and s[0] in "\"'" and s[-1]==s[0]:
        q=s[0];s=s[1:-1];s=s.replace('\\'+q,q)
        if q=='"':s=s.replace('\\"','"')
    return '"'+s.replace('"','\\"').replace('\n','\\a ')+'"'

def unquote(s):
    return s[1:-1] if len(s)>1 and s[0] in "\"'" and s[-1]==s[0] else s

def css_ident(s):
    out=''
    for i,c in enumerate(s):
        if c.isalnum() or c in '_-' or ord(c)>=128:
            if i==0 and c.isdigit():out+='\\'+format(ord(c),'x')+' '
            else:out+=c
        else:out+='\\'+c
    return out or '\\0 '

def rgba(value):
    v=value.strip().lower()
    if v=='transparent':return (0,0,0,0)
    if v in COLORS:v='#'+COLORS[v]
    if re.fullmatch('#[0-9a-f]{3,8}',v):
        h=v[1:]
        if len(h) in (3,4):h=''.join(c*2 for c in h)
        if len(h) in (6,8):return tuple(int(h[i:i+2],16) for i in (0,2,4))+(int(h[6:8],16)/255 if len(h)==8 else 1,)
    m=re.fullmatch(r'(rgba?|hsla?|hwb)\((.*)\)',v,re.S)
    if not m:return None
    try:
        typ,body=m.groups();vals=re.split(r'\s*[,/]\s*|\s+',body.strip());vals=[x for x in vals if x]
        if len(vals) not in (3,4):return None
        alpha=(float(vals[3][:-1])/100 if vals[3].endswith('%') else float(vals[3])) if len(vals)>3 else 1
        alpha=min(1,max(0,alpha))
        def percent(x):return float(x.rstrip('%'))/100
        if typ.startswith('rgb'):
            rgb=[min(255,max(0,float(x[:-1])*2.55 if x.endswith('%') else float(x))) for x in vals[:3]]
        else:
            h=vals[0];ang=re.match(r'^('+NUM+r')(deg|rad|grad|turn)?$',h)
            if not ang:return None
            h=float(ang[1])*{'deg':1,'rad':180/math.pi,'grad':.9,'turn':360,None:1}[ang[2]]/360%1
            if typ=='hwb':
                w,b=map(percent,vals[1:3])
                if w+b>=1:rgb=[255*w/(w+b)]*3
                else:rgb=[255*(x*(1-w-b)+w) for x in colorsys.hsv_to_rgb(h,1,1)]
            else:rgb=[255*x for x in colorsys.hls_to_rgb(h,min(1,max(0,percent(vals[2]))),min(1,max(0,percent(vals[1]))))]
        return tuple(int(math.floor(x+.50000001)) for x in rgb)+(alpha,)
    except:return None

def color(value,mini=False,alphahex=True):
    c=rgba(value)
    if c is None:
        if value.lower()=='currentcolor':return 'currentColor'
        return value
    r,g,b,a=c
    if a<1 and not alphahex:
        sep=',' if mini else ', '
        return 'rgba('+sep.join(map(str,(r,g,b)))+sep+num(a,3)+')'
    h=''.join(f'{max(0,min(255,int(x))):02x}' for x in (r,g,b))
    if a<1:h+=f'{int(math.floor(a*255+.5)):02x}'
    short='#'+(''.join(h[i] for i in range(0,len(h),2)) if all(h[i]==h[i+1] for i in range(0,len(h),2)) else h)
    if len(h)==6 and len(SHORT_COLORS.get(h,'123456789'))<len(short):short=SHORT_COLORS[h]
    return short

def token_value(s,mini=False,typed=True,colors=False,alphahex=True,zero=True):
    """Normalize token spelling without changing unknown CSS grammars."""
    out='';i=0
    while i<len(s):
        c=s[i]
        if c in "\"'":
            e=quoted_end(s,i);out+=css_string(s[i:e]);i=e;continue
        if s.startswith('/*',i):
            e=s.find('*/',i+2);e=len(s) if e<0 else e+2
            if not typed and not mini:out+=s[i:e]
            i=e;continue
        if c.isspace():
            j=i+1
            while j<len(s) and s[j].isspace():j+=1
            out+=(' ' if mini or typed else s[i:j]);i=j;continue
        m=re.match(r'([-a-zA-Z_\u0080-\uffff][\w\-\u0080-\uffff]*)\(',s[i:])
        if m:
            name=m[1];p=i+len(name);e=balanced_end(s,p);whole=s[i:e];inner=s[p+1:e-1] if s[e-1:e]==')' else s[p+1:e]
            if name.lower() in ('rgb','rgba','hsl','hsla','hwb') and rgba(whole) is not None:
                out+=color(whole,mini,alphahex)
            elif name.lower()=='url':
                url=unquote(inner.strip());url=url.replace('\\"','"').replace("\\'", "'")
                if mini and not re.search(r'[\s()"\'\\]',url):out+='url('+url+')'
                else:out+='url('+css_string(url)+')'
            else:
                inn=token_value(inner.strip(),mini,typed,colors,alphahex,zero)
                if typed:
                    inn=re.sub(r'\s*,\s*',',' if mini else ', ',inn)
                    inn=re.sub(r'\s*/\s*','/' if mini else ' / ',inn)
                elif name.lower() in ('var','env'):
                    inn=re.sub(r'\s*,\s*',',' if mini else ', ',inn,count=1)
                out+=name+'('+inn+')'
            i=e;continue
        m=re.match('#[0-9a-fA-F]+',s[i:])
        if m:
            val=m[0];out+=color(val,mini,alphahex) if len(val) in (4,5,7,9) else val;i+=len(val);continue
        m=re.match(NUM+r'([a-zA-Z]+|%)?',s[i:]) if (c.isdigit() or c in '+-.' and i+1<len(s) and (s[i+1].isdigit() or s[i+1]=='.')) else None
        if m:
            val=m[0];u=m[1] or '';x=val[:-len(u)] if u else val;n=num(x)
            if typed and zero and float(x)==0 and u.lower() in LENGTH_UNITS:u=''
            elif typed and u.lower()=='ms':
                n2=num(float(x)/1000)
                if len(n2)+1<len(n)+2:n=n2;u='s'
            out+=n+(u.lower() if typed else u);i+=len(val);continue
        m=re.match(r'[-_a-zA-Z\u0080-\uffff][\w\-\u0080-\uffff]*',s[i:])
        if m:
            word=m[0]
            if colors:word=color(word.lower(),mini,alphahex)
            out+=word;i+=len(m[0]);continue
        out+=c;i+=1
    out=out.strip()
    if typed:
        out=re.sub(r'\s*,\s*',',' if mini else ', ',out)
        out=re.sub(r'\s*/\s*','/' if mini else ' / ',out)
    return out

# Arithmetic values are linear combinations of dimensions. This also permits
# folding expressions that retain a percentage and a relative length.
def dimension(s):
    m=re.fullmatch(r'('+NUM+r')([a-zA-Z]*|%)',s.strip())
    return {m[2].lower():float(m[1])} if m else None

def add_dim(a,b,sign=1):
    if a is None or b is None:return None
    out=dict(a)
    for u,v in b.items():out[u]=out.get(u,0)+sign*v
    return out

def calc_expr(s):
    ts=re.findall(NUM+r'(?:[a-zA-Z]+|%)?|[()+*/-]',s)
    # A minus with spaces is an operator, not the sign of the next token.
    if ''.join(ts).replace(' ','')!=re.sub(r'\s+','',s):return None
    i=0
    def primary():
        nonlocal i
        if i>=len(ts):return None
        if ts[i]=='(':
            i+=1;v=expr()
            if i<len(ts) and ts[i]==')':i+=1
            else:return None
            return v
        v=dimension(ts[i]);i+=1;return v
    def product():
        nonlocal i
        a=primary()
        while i<len(ts) and ts[i] in ('*','/'):
            op=ts[i];i+=1;b=primary()
            if a is None or b is None:return None
            if set(b)=={''}:
                k=b[''];
                if op=='/' and k==0:return None
                a={u:x*(k if op=='*' else 1/k) for u,x in a.items()}
            elif op=='*' and set(a)=={''}:a={u:x*a[''] for u,x in b.items()}
            else:return None
        return a
    def expr():
        nonlocal i
        a=product()
        while i<len(ts):
            if ts[i] in ('+','-'):
                op=ts[i];i+=1;a=add_dim(a,product(),1 if op=='+' else -1)
            elif re.match(r'^[+-]\d|^[+-]\.',ts[i]):a=add_dim(a,product())
            else:break
        return a
    # Split the standalone + token (the number expression omits it).
    ts=re.findall(NUM+r'(?:[a-zA-Z]+|%)?|[()+*/-]',s)
    a=expr()
    return a if i==len(ts) else None

def dim_string(d,calc=True):
    if not d:return '0'
    d={u:v for u,v in d.items() if abs(v)>1e-7}
    if not d:return '0'
    vals=list(d.items());out=''
    for u,x in vals:
        if not out:out=num(x)+u
        else:out+=(' - ' if x<0 else ' + ')+num(abs(x))+u
    return 'calc('+out+')' if len(vals)>1 and calc else out

def math_values(s,mini=False,lower_clamp=False):
    pat=re.compile(r'\b(calc|min|max|clamp)\(')
    i=0;out=''
    while True:
        m=pat.search(s,i)
        if not m:out+=s[i:];break
        out+=s[i:m.start()];e=balanced_end(s,m.end()-1);inner=s[m.end():e-1];fn=m[1]
        inner=math_values(inner,mini,lower_clamp)
        val=None
        if fn=='calc':
            # Nested calc wrappers may be treated as ordinary parentheses.
            d=calc_expr(re.sub(r'\bcalc\(', '(',inner))
            if d is not None:val=dim_string(d)
        else:
            parts=split_top(inner);ds=[calc_expr(re.sub(r'^calc\((.*)\)$',r'\1',p)) for p in parts]
            if ds and all(d is not None and len(d)==1 for d in ds) and len({next(iter(d)) for d in ds})==1:
                u=next(iter(ds[0]));ns=[d[u] for d in ds]
                if fn=='min':x=min(ns)
                elif fn=='max':x=max(ns)
                elif len(ns)==3:x=max(ns[0],min(ns[1],ns[2]))
                else:x=None
                if x is not None:val=num(x)+u
            if val is None and fn=='clamp' and lower_clamp and len(parts)==3:
                sep=',' if mini else ', '
                val='max('+parts[0]+sep+'min('+parts[1]+sep+parts[2]+'))'
        out+=val if val is not None else fn+'('+inner+')';i=e
    return out

def compress_quad(v):
    v=list(v)
    if len(v)==4 and v[3]==v[1]:v.pop()
    if len(v)==3 and v[2]==v[0]:v.pop()
    if len(v)==2 and v[1]==v[0]:v.pop()
    return ' '.join(v)

def expand_quad(v):
    v=words(v)
    if not 1<=len(v)<=4:return None
    return [v[0],v[1] if len(v)>1 else v[0],v[2] if len(v)>2 else v[0],v[3] if len(v)>3 else v[1] if len(v)>1 else v[0]]

def family(v,mini=False,system_fallback=False):
    out=[]
    for f in split_top(v):
        f=f.strip()
        if f.startswith(('"',"'")):
            val=unquote(f)
            if re.fullmatch(r'[-a-zA-Z_][\w -]*',val) and val.lower() not in ('serif','sans-serif','monospace','cursive','fantasy','system-ui','inherit','initial','unset','default'):f=val
            else:f=css_string(f)
        if f=='system-ui' and system_fallback:
            out.extend('system-ui,-apple-system,BlinkMacSystemFont,Segoe UI,Roboto,Noto Sans,Ubuntu,Cantarell,Helvetica Neue'.split(','))
        else:out.append(f)
    out=list(dict.fromkeys(out))
    return (',' if mini else ', ').join(out)

def border(v):
    a=words(v);width='medium';style='none';col='currentColor';extra=[]
    for x in a:
        if x in ('none','hidden','dotted','dashed','solid','double','groove','ridge','inset','outset'):style=x
        elif x in ('thin','medium','thick') or dimension(x) is not None or x.startswith(('calc(','min(','max(','clamp(')):width=x
        elif rgba(x) is not None or x.lower()=='currentcolor':col=x
        else:extra.append(x)
    if extra:return v
    out=[]
    if width!='medium':out.append(width)
    if style!='none':out.append(style)
    if col.lower()!='currentcolor':out.append(col)
    return ' '.join(out) or 'none'

def shadow(v):
    out=[]
    for layer in split_top(v):
        ws=words(layer);col=[];lens=[];ins=[]
        for w in ws:
            if rgba(w) is not None or w=='currentColor':col.append(w)
            elif w=='inset':ins.append(w)
            else:lens.append(w)
        while len(lens)>2 and lens[-1]=='0':lens.pop()
        out.append(' '.join(ins+lens+[c for c in col if c!='currentColor']))
    return out

def timing(v):
    def cb(m):
        try:
            ns=[float(x.strip()) for x in m[1].split(',')]
            return {(0,0,1,1):'linear',(.25,.1,.25,1):'ease',(.42,0,1,1):'ease-in',(0,0,.58,1):'ease-out',(.42,0,.58,1):'ease-in-out'}.get(tuple(ns),m[0])
        except:return m[0]
    v=re.sub(r'cubic-bezier\(([^)]*)\)',cb,v)
    v=re.sub(r'steps\(1,\s*start\)','step-start',v);v=re.sub(r'steps\(1(?:,\s*end)?\)','step-end',v)
    v=re.sub(r'steps\((\d+),\s*end\)',r'steps(\1)',v)
    return v

def transition(v,mini=False):
    result=[]
    for item in split_top(v):
        ts=[];ease='ease';prop='all';behavior='normal';extra=[]
        for w in words(item):
            if re.fullmatch(NUM+'m?s',w):ts.append(w)
            elif w in ('ease','ease-in','ease-out','ease-in-out','linear','step-start','step-end') or w.startswith(('cubic-bezier(','steps(','linear(')):ease=w
            elif w in ('allow-discrete','normal'):behavior=w
            else:prop=w
        ts+=['0s']*(2-len(ts))
        out=[prop]
        if ts[0] not in ('0s','0ms') or ts[1] not in ('0s','0ms'):out.append(ts[0])
        if ease!='ease':out.append(ease)
        if ts[1] not in ('0s','0ms'):out.append(ts[1])
        if behavior!='normal':out.append(behavior)
        result.append(' '.join(out))
    return (',' if mini else ', ').join(result)

def animation(v,mini=False):
    result=[]
    for item in split_top(v):
        ts=[];ease='ease';count='1';direction='normal';fill='none';play='running';name='none';other=[]
        for w in words(item):
            if re.fullmatch(NUM+'m?s',w):ts.append(w)
            elif w in ('ease','ease-in','ease-out','ease-in-out','linear','step-start','step-end') or w.startswith(('cubic-bezier(','steps(','linear(')):ease=w
            elif w in ('normal','reverse','alternate','alternate-reverse'):direction=w
            elif w in ('forwards','backwards','both'):fill=w
            elif w in ('running','paused'):play=w
            elif w=='infinite' or re.fullmatch(NUM,w):count=w
            else:name=unquote(w)
        ts+=['0s']*(2-len(ts));out=[]
        if ts[0] not in ('0s','0ms') or ts[1] not in ('0s','0ms'):out.append(ts[0])
        if ease!='ease':out.append(ease)
        if ts[1] not in ('0s','0ms'):out.append(ts[1])
        if count!='1':out.append(count)
        if direction!='normal':out.append(direction)
        if fill!='none':out.append(fill)
        if play!='running':out.append(play)
        if name!='none' or not out:out.append(name)
        result.append(' '.join(out))
    return (',' if mini else ', ').join(result)

def transform(v,mini=False):
    out='';i=0
    for m in re.finditer(r'([\w]+)\(',v):
        if m.start()<i:continue
        e=balanced_end(v,m.end()-1);a=split_top(v[m.end():e-1]);name=m[1];low=name.lower()
        a=[re.sub(r'^0(?:deg|rad|grad|turn)$','0',x) for x in a]
        if low=='translatex':name='translate'
        elif low=='translate' and len(a)==2 and a[1]=='0':a=a[:1]
        elif low=='translate3d' and len(a)==3:
            if a[0]==a[1]=='0':name='translateZ';a=a[2:]
            elif a[2]=='0':
                name='translate';a=a[:2]
                if a[1]=='0':a=a[:1]
        elif low=='scale' and len(a)==2:
            if a[0]==a[1]:a=a[:1]
            elif mini and a[0]=='1':name='scaleY';a=a[1:]
            elif mini and a[1]=='1':name='scaleX';a=a[:1]
        elif low=='rotatez':name='rotate'
        elif low=='skew' and len(a)==2:
            if a[1]=='0':name='skew';a=a[:1]
            elif mini and a[0]=='0':name='skewY';a=a[1:]
        out+=name+'('+(',' if mini else ', ').join(a)+')';i=e
    return out or v

def gradient(v,mini=False):
    pat=re.compile(r'(?<![-\w])((?:repeating-)?(?:linear|radial|conic)-gradient)\(')
    out='';i=0
    for m in pat.finditer(v):
        if m.start()<i:continue
        out+=v[i:m.start()];e=balanced_end(v,m.end()-1);args=split_top(v[m.end():e-1]);fn=m[1]
        if 'linear' in fn and args:
            if args[0] in ('to bottom','180deg','.5turn'):args.pop(0)
            elif mini:
                args[0]={'to top':'0deg','to right':'90deg','to left':'270deg'}.get(args[0],args[0])
        if 'radial' in fn and args:
            if args[0] in ('ellipse','ellipse farthest-corner','farthest-corner','at center','ellipse at center'):args.pop(0)
            else:args[0]=args[0].replace('ellipse ','').replace(' farthest-corner','').replace(' at center','')
        out+=fn+'('+(',' if mini else ', ').join(args)+')';i=e
    return out+v[i:]

def position(v,mini=False):
    ws=words(v)
    if len(ws)==2 and ws[0] in ('top','bottom') and ws[1] in ('left','right','center'):ws.reverse()
    if mini:
        if len(ws)==1 and ws[0] in ('top','bottom'):ws=['50%',{'top':'0','bottom':'100%'}[ws[0]]]
        else:ws=[{'left':'0','top':'0','center':'50%','right':'100%','bottom':'100%'}.get(x,x) for x in ws]
        if len(ws)==2 and ws[1]=='50%':ws.pop()
        if len(ws)==2 and ws==['50%','50%']:ws.pop()
    elif len(ws)==2 and ws[1]=='center' and ws[0] in ('left','right','center'):ws.pop()
    elif len(ws)==2 and ws[0]=='center' and ws[1] in ('top','bottom'):ws=ws[1:]
    return ' '.join(ws)

